const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
const contents={bio:`<p class="eyebrow">Trayectoria</p><h2>Una vida dedicada a la historia</h2><p>Germán Rodrigo Mejía Pavony nació en Pereira en 1954. Es licenciado en Filosofía y Letras con especialización en Historia de la Pontificia Universidad Javeriana y doctor en Historia de América Latina de la Universidad de Miami.</p><p>Fue decano de la Facultad de Ciencias Sociales de la Universidad Javeriana y director del Archivo de Bogotá. Su trabajo vincula la historia urbana, la investigación, la docencia y la divulgación.</p><p>Continúa compartiendo su conocimiento en conferencias, encuentros académicos y conversaciones de radio.</p><a href="https://javeriana.academia.edu/Germ%C3%A1nMej%C3%ADa/CurriculumVitae" target="_blank" rel="noopener">Consultar hoja de vida en Academia.edu ↗</a><p class="notice">La hoja de vida enlazada es una versión histórica y no recoge toda su actividad reciente.</p>`,talks:`<p class="eyebrow">Conferencias y encuentros</p><h2>Diálogos para comprender nuestro tiempo</h2><h3>Bogotá: ciudad y memoria</h3><p>La ciudad colonial, sus transformaciones urbanas y las historias de sus habitantes.</p><h3>Colombia: historia y sociedad</h3><p>La construcción del país, sus procesos históricos y las preguntas sobre nuestro pasado.</p><h3>América Latina: una historia urbana</h3><p>Las ciudades latinoamericanas y las relaciones entre territorio, sociedad e historia.</p>`,book1:`<h2>Los años del cambio</h2><img class="detail-cover" src="assets/los-anos-del-cambio-fast.webp" alt="Los años del cambio" width="700" height="933" decoding="async" srcset="/assets/los-anos-del-cambio-fast-responsive-320.webp 320w, /assets/los-anos-del-cambio-fast-responsive-640.webp 640w, /assets/los-anos-del-cambio-fast.webp 700w" sizes="(max-width: 720px) 45vw, 320px"><p>Historia urbana de Bogotá, 1820–1910.</p><p>Germán Rodrigo Mejía Pavony. Primera edición de 1999; segunda edición de 2000.</p><a href="https://www.tornamesa.co/autor/german-rodrigo-mejia-pavony/" target="_blank" rel="noopener">Consultar catálogo del autor ↗</a>`,book2:`<h2>La ciudad de los conquistadores</h2><img class="detail-cover" src="assets/la-ciudad-de-los-conquistadores-original.webp" alt="La ciudad de los conquistadores" width="251" height="380" decoding="async"><p>Historia de Bogotá, 1536–1604.</p><p>Germán Rodrigo Mejía Pavony. Editorial Pontificia Universidad Javeriana, 2012.</p><a href="https://javeriana.academia.edu/GermanMejiaPavony" target="_blank" rel="noopener">Consultar publicaciones del autor ↗</a>`,book3:`<h2>La aventura urbana de América Latina</h2><img class="detail-cover" src="assets/la-aventura-urbana-original.webp" alt="La aventura urbana de América Latina" width="250" height="386" decoding="async"><p>Germán Rodrigo Mejía Pavony. Fundación Mapfre / Taurus, 2013.</p><a href="https://www.penguinlibros.com/es/994620-german-r-mejia-pavony" target="_blank" rel="noopener">Consultar en Penguin Libros ↗</a>`,credits:`<h2>Créditos y fuentes</h2><p>Hero: montaje de once segundos en 768p a partir de la imagen aprobada y dos fotografías históricas suministradas. Fotografías históricas con ajuste conservador de contraste y nitidez. Movimiento recreado con MiniMax Hailuo 2.3 a 768p y acelerado para un efecto timelapse; no es una filmación histórica. Apertura a color animada con movimiento del cielo y la plaza. Carátulas originales con un ajuste conservador de nitidez, sin rediseño.</p><p>Fotografías de Germán y del estudio de radio: materiales suministrados para este proyecto.</p><p>Plaza de Bolívar: Gabriel Leonardo Guerrero / DeMentePhoto, Wikimedia Commons, CC BY-SA 4.0. <a href="https://commons.wikimedia.org/wiki/File:Panor%C3%A1mica_Plaza_de_Bol%C3%ADvar_Bogot%C3%A1.jpg" target="_blank" rel="noopener">Wikimedia Commons</a>.</p><p>Portadas editoriales: fuentes bibliográficas enlazadas. Ilustraciones temáticas generadas para esta propuesta.</p><p>Fuentes de trayectoria: hoja de vida en Academia.edu y perfiles institucionales de la Universidad Javeriana.</p>`};
const dialog=document.querySelector('dialog'),body=document.querySelector('#dialog-content');let lastFocus;function openDetail(key){if(!contents[key])return;lastFocus=document.activeElement;body.innerHTML=contents[key];if(!dialog.open)dialog.showModal();document.body.style.overflow='hidden';dialog.scrollTop=0}document.addEventListener('click',e=>{const b=e.target.closest('[data-open]');if(b)openDetail(b.dataset.open)});document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.style.overflow='';lastFocus?.focus()});



const heroVideo=document.querySelector('.hero-video');if(heroVideo){const startVideo=()=>{heroVideo.muted=true;if(!heroVideo.src)heroVideo.src=heroVideo.dataset.src;heroVideo.play().catch(()=>{});};const cover=document.querySelector('.hero>img');heroVideo.addEventListener('playing',()=>heroVideo.closest('.hero').classList.add('video-ready'));heroVideo.addEventListener('error',()=>heroVideo.closest('.hero').classList.remove('video-ready'));if(cover&&!cover.complete)cover.addEventListener('load',startVideo,{once:true});else startVideo();document.addEventListener('visibilitychange',()=>{if(document.hidden)heroVideo.pause();else startVideo();});}



const dropdowns=[...document.querySelectorAll("header details")];dropdowns.forEach(d=>d.addEventListener("toggle",()=>{if(d.open)dropdowns.forEach(other=>{if(other!==d)other.open=false})}));document.addEventListener("click",e=>{dropdowns.forEach(d=>{if(!d.contains(e.target))d.open=false});if(e.target.closest("[data-language-current]")){e.preventDefault();dropdowns.forEach(d=>d.open=false)}});document.addEventListener("keydown",e=>{if(e.key==="Escape")dropdowns.forEach(d=>{if(d.open){d.open=false;d.querySelector("summary").focus()}})});
